import { generateUUID, compressBase64, decompressBase64 } from "../../components/utilities/utils";
import api from "../../components/api/AccWebcall";
import appsettings from "../../appsettings.json"

const apiendpoints = appsettings.ApiEndpoints;

export const GetAppDate = async (filterid, erdate) => {

    let Response;

    const convID = generateUUID();
    const frmHdr = { convid: convID, tag: "Application Date", orgid: "", vendid: "_Acc" };
    const frmData = {};
    const data = { hdr: frmHdr, body: frmData };

    const reqHdr = {};

    await api.post(apiendpoints.AppDate, compressBase64(data), reqHdr)
        .then(function (response) {
            const strResponse = JSON.parse(decompressBase64(response.data));
            Response = strResponse.body;
        });

    return Response;

};
