import React from "react";
import { useState, useEffect, useRef } from "react";
import { useForm } from "react-hook-form";
import { toast } from "react-toastify";
import Select from "react-select";
import { GetAppDate } from "../dataservice/getAppDate";
import { GetQData } from "../dataservice/getQData";
import { GetVoucherData } from "../dataservice/getVoucherData";
import { GetActionList } from "../dataservice/getActionList";
import { useSearchParams, useNavigate } from "react-router-dom";

import { generateUUID, compressBase64, decompressBase64 } from "../../components/utilities/utils";

import apiAcc from "../../components/api/AccWebcall";
import api from "../../components/api/Webcall";
import appsettings from "../../appsettings.json"
const apiendpoints = appsettings.ApiEndpoints;

function ReceiptApprove() {

    const navigate = useNavigate();
    const { register, handleSubmit, getValues, setValue } = useForm();
    const [searchParams, setSearchParams] = useSearchParams();

    let qDet = useRef(JSON.parse(decompressBase64(atob(searchParams.get("_q")))));
    let isVoUpdated = useRef(false);

    const [qData, setQData] = useState(null);
    const [actLst, setActionLst] = useState([]);

    const onSubmit = (e) => {
        
        let action = getValues("cmbAction");
        let toSubmit = true;

        if (action == 5 && isVoUpdated.current == false) {

            let frmData = qData;

            const convID = generateUUID();
            const frmHdr = { convid: convID, tag: "Update VO Data", orgid: "", vendid: "_Acc" };
            const data = { hdr: frmHdr, body: frmData };
            const reqHdr = {};
            apiAcc.post(apiendpoints.UpdVoData, compressBase64(data), reqHdr)
                .then(function (response) {
                    const res = JSON.parse(decompressBase64(response.data));
                    if (res) {
                        if (res.hdr) {
                            if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {

                                e.target.disabled = false;

                                toSubmit = false;
                                isVoUpdated = false;

                                if (res.fdr) {
                                    setTimeout(() => {

                                        let strMsg = "";
                                        res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                                        toast.error(strMsg);

                                    }, 300);
                                }
                            }
                            else {
                                
                                toSubmit = true;
                                isVoUpdated = true;

                            }
                        }
                    }
                });
        }


        if (toSubmit === true) {

            let frmData = qData;

            /* Validate Data */
            frmData["_QMovement"] = {};
            frmData["_QMovement"]["_cmbAction"] = getValues("cmbAction");
            frmData["_QMovement"]["_Comment"] = getValues("txtComment");
            frmData["_QMovement"]["_StartTime"] = qDet.current.starttime;

            const convID = generateUUID();
            const frmHdr = { convid: convID, tag: "Submit Q", orgid: "", vendid: "_Acc" };
            const data = { hdr: frmHdr, body: frmData, _sev: qDet.current };
            const reqHdr = {};
            api.post(apiendpoints.CScrSubmitQ, compressBase64(data), reqHdr)
                .then(function (response) {
                    const res = JSON.parse(decompressBase64(response.data));

                    if (res) {
                        if (res.hdr) {
                            if (res.hdr.rst && res.hdr.rst != "SUCCESS") {

                                e.target.disabled = false;

                                if (res.fdr) {
                                    setTimeout(() => {

                                        let strMsg = "";
                                        res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                                        toast.error(strMsg);

                                    }, 300);
                                }
                            }
                            else {

                                setTimeout(() => { toast.success("Successfully submited"); }, 300);
                                navigate("/Home");
                            }
                        }
                    }

                });
        }

    }

    const fetchActionList = async () => {
        const actLst = await GetActionList(qDet.current.stgid);
        if (actLst) {
            if (actLst.hdr) {
                if (actLst.hdr.rst && actLst.hdr.rst !== "SUCCESS") {

                    if (actLst.fdr) {
                        setTimeout(() => {

                            let strMsg = "";
                            actLst.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                            toast.error(strMsg);

                        }, 300);
                    }
                }
                else {
                    setActionLst(actLst.body.act);
                }
            }
        }
    }

    const fetchVoData = () => {

        const convID = generateUUID();
        const frmHdr = { convid: convID, tag: "Q Data", orgid: "", vendid: "_Acc" };
        const frmData = { qid: qDet.current.qid, scrid: qDet.current.scrid, stgid: qDet.current.stgid };
        const data = { hdr: frmHdr, body: frmData };
        const reqHdr = {};
        api.post(apiendpoints.CScrQData, compressBase64(data), reqHdr)
            .then(function (response) {
                const qData = JSON.parse(decompressBase64(response.data));

                if (qData) {
                    if (qData.hdr) {
                        if (qData.hdr.rst && qData.hdr.rst !== "SUCCESS") {
                            if (qData.fdr) {

                                setTimeout(() => {
                                    let strMsg = "";
                                    qData.fdr.map((data) => { strMsg += data.rstmsg + ", " });
                                    toast.error(strMsg);
                                }, 300);
                            }
                        }
                        else {

                            qData.body["_stage"] = "approval";
                            const convID = generateUUID();
                            const frmHdr = { convid: convID, tag: "Screen Transaction Data", orgid: "", vendid: "_Acc" };
                            const data = { hdr: frmHdr, body: qData.body };
                            const reqHdr = {};
                            apiAcc.post(apiendpoints.VoData, compressBase64(data), reqHdr)
                                .then(function (response) {
                                    const voData = JSON.parse(decompressBase64(response.data));
                                    if (voData) {
                                        if (voData.hdr) {
                                            if (voData.hdr.rst && voData.hdr.rst !== "SUCCESS") {
                                                if (voData.fdr) {

                                                    setTimeout(() => {
                                                        let strMsg = "";
                                                        qData.fdr.map((data) => { strMsg += data.rstmsg + ", " });
                                                        toast.error(strMsg);
                                                    }, 300);
                                                }
                                            }
                                            else
                                                {
                                                    setQData(voData.body.vodata);
                                                }
                                        }
                                    }

                                });
                        }
                    }
                }

            });
    }


    const onCancel = (e) => {

        let frmData = {};
        const convID = generateUUID();
        const frmHdr = { convid: convID, tag: "Cancel Q", orgid: "", vendid: "_Acc" };
        const data = { hdr: frmHdr, body: frmData, _qdet: qDet.current };
        const reqHdr = {};
        api.post(apiendpoints.CScrCancelQ, compressBase64(data), reqHdr)
            .then(function (response) {
                const res = JSON.parse(decompressBase64(response.data));

                if (res) {
                    if (res.hdr) {
                        if (res.hdr.rst && res.hdr.rst != "SUCCESS") {

                            e.target.disabled = false;

                            if (res.fdr) {
                                setTimeout(() => {

                                    let strMsg = "";
                                    res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                                    toast.error(strMsg);

                                }, 300);
                            }
                        }
                        else {
                            setTimeout(() => { toast.success("Successfully cancled"); }, 300);
                            navigate("/Home");
                        }
                    }
                }

            });
    }

    /* Use Effect */
    useEffect(() => {
        setTimeout(() => {
            fetchActionList();
            fetchVoData();
        }, 1000);
    }, []);

    
    return (

        <>
            {(qData !== null) ? <>

                <div className="row pad-top-0-5em pad-left-15">
                    <div className="card-header">
                        <strong className="card-title">Receipt Approval</strong>
                    </div>
                </div>

                <div className="row">

                    <div className="col-md-9 pad-left-2em">

                        <div className="row pad-bottom-0-5em">

                            <div className="col-md-4">
                                <label htmlFor="txtDate" className="form-label hl">Date</label>
                                <label id="txtDate" className="form-control">{qData.valdt}</label>
                            </div>

                            <div className="col-md-8">
                                <label htmlFor="cmbLedgerId" className="form-label hl">Debit Ledger</label>
                                <label id="cmbLedgerId" className="form-control">{qData.lgrna}</label>
                            </div>

                        </div>

                        <div className="row pad-bottom-0-5em">

                            <div className="col-md-4">
                                <label htmlFor="txtAmount" className="form-label hl">Amount</label>
                                <label id="txtAmount" className="form-control">{qData.amt}</label>
                            </div>

                            <div className="col-md-2">
                                <label htmlFor="txtCurrency" className="form-label hl">Currency</label>
                                <label id="txtCurrency" className="form-control">{qData.curr}</label>
                            </div>

                            <div className="col-md-3">
                                <label htmlFor="txtExcngRate" className="form-label hl">Exchange Rate</label>
                                <label id="txtExcngRate" className="form-control">{qData.exrate}</label>
                            </div>

                            <div className="col-md-3">
                                <label htmlFor="txtLcAmount" className="form-label hl">LC Value</label>
                                <label id="txtLcAmount" className="form-control">{qData.lcamt}</label>
                            </div>

                        </div>

                        <div className="row pad-bottom-0-5em">

                            <div className="col-md-12">
                                <label htmlFor="txtNaration" className="form-label hl">Naration</label>
                                <label id="txtNaration" className="form-control">{qData.narr}</label>
                            </div>

                        </div>

                        <br />

                        <div className="row">

                            <div className="col-md-4">
                                <label htmlFor="cmbLedgerId_1" className="form-label hl">Credit Ledger</label>
                            </div>

                            <div className="col-md-1">
                                <label htmlFor="txtCurrency_1" className="form-label hl">Currency</label>
                            </div>

                            <div className="col-md-3">
                                <label htmlFor="txtAmount_1" className="form-label hl">Amount</label>
                            </div>

                            <div className="col-md-1">
                                <label htmlFor="txtExcngRate_1" className="form-label hl">Ex Rate</label>
                            </div>

                            <div className="col-md-2">
                                <label htmlFor="txtLcAmount_1" className="form-label hl">LC Value</label>
                            </div>

                        </div>


                        {qData.det.map((data) => {
                            return (

                                <div className="row">

                                    <div className="col-md-4">
                                        <label id="grcmbLedgerId" className="form-control">{data["lgrna"]}</label>
                                    </div>

                                    <div className="col-md-1">
                                        <label id="grtxtCurrency" className="form-control">{data["curr"]}</label>
                                    </div>

                                    <div className="col-md-3">
                                        <label id="grtxtAmount" className="form-control">{data["amt"]}</label>
                                    </div>

                                    <div className="col-md-1">
                                        <label id="grtxtExcngRate" className="form-control">{data["exrate"]}</label>
                                    </div>

                                    <div className="col-md-3">
                                        <label id="grtxtLcAmount" className="form-control">{data["lcamt"]}</label>
                                    </div>

                                </div>
                            )

                        })}

                    </div>


                    <div className="col-md-3">

                        <div className="row col-md-12 pad-bottom-0-5em" >

                            <label htmlFor="cmbAction" className="form-label">Action</label>

                            <select {...register("cmbAction")} className="form-control" >
                                <option value="">- Select -</option>
                                {(actLst) ?
                                    actLst.map((i) =>
                                        (<option key={i.actid} value={i.actid}>{i.actna}</option>))
                                    : ""}
                            </select>

                        </div>

                        <div className="row col-md-12 pad-bottom-0-5em" >
                            <label htmlFor="txtComment" className="form-label">Comment</label>
                            <textarea type="text" className="form-control" {...register("txtComment")} rows="3" ></textarea>
                        </div>

                        <div className="row  col-md-12">

                            <button className="btn btn-hover color-5 btn-sm  m-2" type="button" 
                                    onClick={(e) => { onSubmit(e); e.target.disabled = true; } } >
                                Submit
                            </button>

                            <button className="btn btn btn-hover color-10 btn-sm  m-2" type="button" 
                                    onClick={(e) => { onCancel(e);  e.target.disabled = true; }} >
                                Cancel
                            </button>

                        </div>


                    </div>

                </div>

            </> : <> <h4> Loading.... </h4> </>}


        </>
    );
}

export default ReceiptApprove;
